// Store tokens and track SLA
const loginResponse = $input.first().json;
const startTime = Date.now();

if (!loginResponse.accessToken) {
  throw new Error('Login failed: No access token received');
}

return [{
  json: {
    accessToken: loginResponse.accessToken,
    refreshToken: loginResponse.refreshToken,
    expiresIn: loginResponse.expiresIn,
    user: loginResponse.user,
    tokenAcquiredAt: new Date().toISOString(),
    testRunId: `RUN-${Date.now()}`,
    testResults: [],
    startTime
  }
}];

// Parse OpenAPI spec and extract testable endpoints
const spec = $input.first().json;
const tokenData = $('Store Tokens & Init Run').first().json;

const endpoints = [];
for (const [path, methods] of Object.entries(spec.paths || {})) {
  for (const [method, details] of Object.entries(methods)) {
    endpoints.push({
      method: method.toUpperCase(),
      path,
      summary: details.summary || '',
      tags: details.tags || [],
      requiresAuth: !!details.security || !!spec.security,
      parameters: details.parameters || [],
      requestBody: details.requestBody || null,
      expectedResponses: Object.keys(details.responses || {}).map(Number)
    });
  }
}

return [{
  json: {
    endpoints,
    totalEndpoints: endpoints.length,
    spec,
    tokenData,
    parsedAt: new Date().toISOString()
  }
}];

// Update the access token after refresh
const refreshResponse = $input.first().json;
if (!refreshResponse.accessToken) {
  throw new Error('Token refresh failed');
}
return [{ json: { newAccessToken: refreshResponse.accessToken, newRefreshToken: refreshResponse.refreshToken } }];

// Collect all test results and compute pass/fail metrics
const tests = [
  { name: 'POST /auth/login',         node: '1. Login - Get Tokens',          expectedStatus: 200 },
  { name: 'GET /airports',            node: '2. Test: GET /airports',          expectedStatus: 200 },
  { name: 'GET /airports/:code',      node: '3. Test: GET /airports/JFK',      expectedStatus: 200 },
  { name: 'GET /flights/search',      node: '4. Test: GET /flights/search',    expectedStatus: 200 },
  { name: 'GET /flights/:id',         node: '5. Test: GET /flights/FL001',     expectedStatus: 200 },
  { name: 'GET /seats/:flightId',     node: '6. Test: GET /seats/FL001',       expectedStatus: 200 },
  { name: 'POST /passengers',         node: '7. Test: POST /passengers',       expectedStatus: 201 },
  { name: 'GET /passengers/:id',      node: '8. Test: GET /passengers/P001',   expectedStatus: 200 },
  { name: 'POST /bookings',           node: '9. Test: POST /bookings',         expectedStatus: 201 },
  { name: 'GET /bookings/:id',        node: '10. Test: GET /bookings/BK001',   expectedStatus: 200 },
  { name: 'POST /auth/refresh',       node: '11. Refresh Access Token',        expectedStatus: 200 },
  { name: 'POST /check-in',           node: '12. Test: POST /check-in',        expectedStatus: 200 },
  { name: 'GET /baggage/allowance',   node: '13. Test: GET /baggage/allowance',expectedStatus: 200 },
  { name: 'POST /payments',           node: '14. Test: POST /payments',        expectedStatus: 201 },
  { name: 'PUT /bookings/cancel(neg)',node: '15. Test: PUT /bookings/cancel (Neg)', expectedStatus: 403 },
];

const SLA_THRESHOLD_MS = 2000;
const results = [];
let passed = 0;
let failed = 0;
let slaViolations = 0;

for (const test of tests) {
  try {
    const nodeData = $node[test.node]?.json;
    const statusCode = nodeData?._statusCode || nodeData?.statusCode || 200;
    const responseTime = nodeData?._responseTime || 0;
    const slaViolated = responseTime > SLA_THRESHOLD_MS;

    const testPassed = statusCode === test.expectedStatus;
    if (testPassed) passed++; else failed++;
    if (slaViolated) slaViolations++;

    results.push({
      endpoint: test.name,
      status: testPassed ? 'PASS' : 'FAIL',
      expectedStatus: test.expectedStatus,
      actualStatus: statusCode,
      responseTimeMs: responseTime,
      slaViolated,
      slaThresholdMs: SLA_THRESHOLD_MS
    });
  } catch (e) {
    failed++;
    results.push({
      endpoint: test.name,
      status: 'ERROR',
      error: e.message,
      expectedStatus: test.expectedStatus,
      actualStatus: null
    });
  }
}

const runId = $('Store Tokens & Init Run').first().json.testRunId;
const summary = {
  testRunId: runId,
  completedAt: new Date().toISOString(),
  total: tests.length,
  passed,
  failed,
  slaViolations,
  passRate: `${Math.round((passed / tests.length) * 100)}%`,
  overallStatus: failed === 0 ? 'SUCCESS' : 'FAILURE'
};

return [{ json: { summary, results, hasFailures: failed > 0, hasSlaViolations: slaViolations > 0 } }];

